#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "trmm.h"

void init_array(
    int m,
    int n,
    double *alpha,
    double A[20][20],
    double B[20][30]) {
    int i, j;

    *alpha = 1.5;
    for (i = 0; i < m; i++) {
        for (j = 0; j < i; j++) {
            A[i][j] = (double)((i + j) % m) / m;
